// BillingServiceHandler is an implementation of the everstack.billing.v1.BillingService service.
type BillingServiceHandler interface {
	// GetSubscription returns the subscription for an organization
	GetSubscription(context.Context, *connect.Request[v1.GetSubscriptionRequest]) (*connect.Response[v1.GetSubscriptionResponse], error)
	// CreateCheckoutSession creates a Stripe checkout session for plan upgrade
	CreateCheckoutSession(context.Context, *connect.Request[v1.CreateCheckoutSessionRequest]) (*connect.Response[v1.CreateCheckoutSessionResponse], error)
	// CreateBillingPortalSession creates a Stripe billing portal session
	CreateBillingPortalSession(context.Context, *connect.Request[v1.CreateBillingPortalSessionRequest]) (*connect.Response[v1.CreateBillingPortalSessionResponse], error)
	// CancelSubscription cancels a subscription at period end
	CancelSubscription(context.Context, *connect.Request[v1.CancelSubscriptionRequest]) (*connect.Response[v1.CancelSubscriptionResponse], error)
	// ResumeSubscription resumes a cancelled subscription
	ResumeSubscription(context.Context, *connect.Request[v1.ResumeSubscriptionRequest]) (*connect.Response[v1.ResumeSubscriptionResponse], error)
	// ListInvoices lists invoices for an organization
	ListInvoices(context.Context, *connect.Request[v1.ListInvoicesRequest]) (*connect.Response[v1.ListInvoicesResponse], error)
	// GetUsage returns current usage metrics for an organization
	GetUsage(context.Context, *connect.Request[v1.GetUsageRequest]) (*connect.Response[v1.GetUsageResponse], error)
	// GetUsageHistory returns time-series usage data for charts.
	// Aggregates across instances when instance_id is empty.
	GetUsageHistory(context.Context, *connect.Request[v1.GetUsageHistoryRequest]) (*connect.Response[v1.GetUsageHistoryResponse], error)
	// ReportUsage reports usage for metered billing (for license service)
	ReportUsage(context.Context, *connect.Request[v1.ReportUsageRequest]) (*connect.Response[v1.ReportUsageResponse], error)
	// ReportOverageUsage reports overage usage to Stripe Meters (for license service)
	ReportOverageUsage(context.Context, *connect.Request[v1.ReportOverageUsageRequest]) (*connect.Response[v1.ReportOverageUsageResponse], error)
	// ReportInstanceSnapshot records a per-instance daily snapshot of resource
	// counts (agents, datasets, etc.) for historical usage charts.
	ReportInstanceSnapshot(context.Context, *connect.Request[v1.ReportInstanceSnapshotRequest]) (*connect.Response[v1.ReportInstanceSnapshotResponse], error)
	// SyncPlans syncs plans from plans.json to Stripe (admin only)
	SyncPlans(context.Context, *connect.Request[v1.SyncPlansRequest]) (*connect.Response[v1.SyncPlansResponse], error)
	// GetPlans returns the current synced plan IDs and plan definitions
	GetPlans(context.Context, *connect.Request[v1.GetPlansRequest]) (*connect.Response[v1.GetPlansResponse], error)
	// GetPendingActivation retrieves pending activation tokens for an organization
	GetPendingActivation(context.Context, *connect.Request[v1.GetPendingActivationRequest]) (*connect.Response[v1.GetPendingActivationResponse], error)
	// RetryActivation attempts to retry the gateway activation callback
	RetryActivation(context.Context, *connect.Request[v1.RetryActivationRequest]) (*connect.Response[v1.RetryActivationResponse], error)
	// RegenerateActivation regenerates an activation token for an organization
	RegenerateActivation(context.Context, *connect.Request[v1.RegenerateActivationRequest]) (*connect.Response[v1.RegenerateActivationResponse], error)
	// GetActivationStatus checks the processing status of webhook events
	GetActivationStatus(context.Context, *connect.Request[v1.GetActivationStatusRequest]) (*connect.Response[v1.GetActivationStatusResponse], error)
	// GetInstanceOrganization looks up the organization associated with a gateway instance
	GetInstanceOrganization(context.Context, *connect.Request[v1.GetInstanceOrganizationRequest]) (*connect.Response[v1.GetInstanceOrganizationResponse], error)
	// CreateInstanceMapping creates a mapping between a gateway instance and an organization
	CreateInstanceMapping(context.Context, *connect.Request[v1.CreateInstanceMappingRequest]) (*connect.Response[v1.CreateInstanceMappingResponse], error)
	// GetSpendLimits retrieves all spend limits for an organization
	GetSpendLimits(context.Context, *connect.Request[v1.GetSpendLimitsRequest]) (*connect.Response[v1.GetSpendLimitsResponse], error)
	// SetSpendLimit creates or updates a spend limit
	SetSpendLimit(context.Context, *connect.Request[v1.SetSpendLimitRequest]) (*connect.Response[v1.SetSpendLimitResponse], error)
	// DeleteSpendLimit removes a spend limit
	DeleteSpendLimit(context.Context, *connect.Request[v1.DeleteSpendLimitRequest]) (*connect.Response[v1.DeleteSpendLimitResponse], error)
	// MigrateSubscription migrates a multi-item subscription to single-item (admin only)
	MigrateSubscription(context.Context, *connect.Request[v1.MigrateSubscriptionRequest]) (*connect.Response[v1.MigrateSubscriptionResponse], error)
	// AdjustSeats changes the number of paid extra admin seats on an
	// org's subscription. Positive delta adds, negative removes (clamped
	// at 0). Free / Enterprise tiers reject. Stripe handles proration on
	// the per-seat line item with create_prorations.
	AdjustSeats(context.Context, *connect.Request[v1.AdjustSeatsRequest]) (*connect.Response[v1.AdjustSeatsResponse], error)
}

